from __future__ import annotations

import random
from typing import Any

import reflex as rx

from ..sample import CELLS
from .hybrid import cell_view, chrome

BG_DIM, BG0, BG1, BG2, BG3, BG4 = "#232a2e", "#2d353b", "#343f44", "#3d484d", "#475258", "#4f585e"
FG, GREEN, BLUE, GREY1, GREY2 = "#d3c6aa", "#a7c080", "#7fbbb3", "#859289", "#9da9a0"
MONO = "JetBrainsMono Nerd Font, JetBrains Mono, monospace"

COLUMNS = [
    ("name", "str", 180),
    ("kind", "str", 120),
    ("price", "float", 110),
    ("stock", "int", 100),
    ("rating", "float", 100),
]


def _fake_rows(count: int = 240) -> list[list[Any]]:
    """Deterministic made-up rows, enough of them that scrolling and sorting mean something."""
    rng = random.Random(7)
    kinds = ["potion", "tool", "weapon", "armor", "food"]
    stems = ["ether", "elixir", "rope", "lantern", "dagger", "buckler", "ration", "tonic", "pick", "cloak"]
    return [
        [
            f"{rng.choice(stems)}-{i:03d}",
            rng.choice(kinds),
            round(rng.uniform(2, 90), 1),
            rng.randint(0, 400),
            round(rng.uniform(1, 5), 2),
        ]
        for i in range(count)
    ]


ROWS = _fake_rows()
KIND_INDEX = 1
PRICE_INDEX = 2
CHART_DATA = [
    {
        "kind": kind,
        "avg_price": round(
            sum(r[PRICE_INDEX] for r in ROWS if r[KIND_INDEX] == kind) / sum(1 for r in ROWS if r[KIND_INDEX] == kind),
            1,
        ),
    }
    for kind in sorted({r[KIND_INDEX] for r in ROWS})
]

GRID_THEME = {
    "accent_color": BLUE,
    "accent_fg": BG0,
    "accent_light": "rgba(127, 187, 179, 0.16)",
    "bg_cell": BG0,
    "bg_cell_medium": BG1,
    "bg_header": BG1,
    "bg_header_has_focus": BG2,
    "bg_header_hovered": BG2,
    "bg_search_result": BG3,
    "border_color": BG2,
    "horizontal_border_color": BG2,
    "header_bottom_border_color": BG4,
    "text_dark": FG,
    "text_medium": GREY2,
    "text_light": GREY1,
    "text_header": FG,
    "text_header_selected": BG0,
    "text_bubble": FG,
    "bg_bubble": BG2,
    "font_family": MONO,
    "base_font_style": "13px",
    "header_font_style": "600 13px",
}


class ViewerState(rx.State):
    """Filter, sort, column widths and active tab of the data viewer."""

    query: str = ""
    sort_col: int = -1
    sort_desc: bool = False
    widths: list[int] = [width for _, _, width in COLUMNS]
    tab: str = "table"

    @rx.var
    def rows(self) -> list[list[Any]]:
        needle = self.query.strip().lower()
        rows = [r for r in ROWS if needle in " ".join(str(v) for v in r).lower()] if needle else list(ROWS)
        if self.sort_col >= 0:
            rows.sort(key=lambda r: r[self.sort_col], reverse=self.sort_desc)
        return rows

    @rx.var
    def row_count(self) -> int:
        return len(self.rows)

    @rx.var
    def columns(self) -> list[dict[str, Any]]:
        arrow = " ▼" if self.sort_desc else " ▲"
        return [
            {"title": name + (arrow if i == self.sort_col else ""), "id": name, "type": kind, "width": self.widths[i]}
            for i, (name, kind, _) in enumerate(COLUMNS)
        ]

    @rx.var
    def summary(self) -> str:
        shown = len(self.rows)
        suffix = "" if shown == len(ROWS) else f" of {len(ROWS)}"
        return f"{shown}{suffix} rows × {len(COLUMNS)} cols"

    @rx.event
    def set_query(self, value: str):
        self.query = value

    @rx.event
    def set_tab(self, tab: str):
        self.tab = tab

    @rx.event
    def header_clicked(self, pos: tuple[int, int]):
        """Cycle a column through ascending -> descending -> unsorted."""
        # Glide sends the bare column index here, despite the (col, row) tuple in Reflex's event spec.
        col = pos if isinstance(pos, int) else pos[0]
        if col != self.sort_col:
            self.sort_col, self.sort_desc = col, False
        elif not self.sort_desc:
            self.sort_desc = True
        else:
            self.sort_col, self.sort_desc = -1, False

    @rx.event
    def column_resized(self, column: dict[str, Any], width: int):
        names = [name for name, _, _ in COLUMNS]
        if column.get("id") in names:
            self.widths[names.index(column["id"])] = int(width)


def _tab(name: str, label: str) -> rx.Component:
    return rx.el.button(
        label,
        on_click=ViewerState.set_tab(name),
        class_name=rx.cond(ViewerState.tab == name, "viewer-tab is-active", "viewer-tab"),
    )


def _grid() -> rx.Component:
    return rx.el.div(
        rx.data_editor(
            columns=ViewerState.columns,
            data=ViewerState.rows,
            rows=ViewerState.row_count,
            theme=GRID_THEME,
            row_markers="number",
            row_height=28,
            header_height=32,
            smooth_scroll_x=True,
            smooth_scroll_y=True,
            column_select="none",
            on_header_clicked=ViewerState.header_clicked,
            on_column_resize=ViewerState.column_resized,
            height="320px",
        ),
        class_name="viewer-grid",
    )


def _chart() -> rx.Component:
    return rx.el.div(
        rx.recharts.bar_chart(
            rx.recharts.cartesian_grid(stroke=BG3, vertical=False),
            rx.recharts.bar(data_key="avg_price", fill=GREEN, radius=[3, 3, 0, 0], is_animation_active=False),
            rx.recharts.x_axis(data_key="kind", stroke=GREY1),
            rx.recharts.y_axis(stroke=GREY1),
            rx.recharts.graphing_tooltip(
                cursor={"fill": BG1},
                content_style={"background": BG_DIM, "border": f"1px solid {BG4}", "borderRadius": "6px"},
                item_style={"color": FG},
            ),
            data=CHART_DATA,
            width="100%",
            height=300,
        ),
        class_name="viewer-chart",
    )


def data_viewer() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("items", class_name="viewer-name mono"),
            rx.el.span(ViewerState.summary, class_name="dim"),
            rx.el.span(class_name="spacer"),
            rx.el.input(placeholder="Filter rows…", on_change=ViewerState.set_query, class_name="viewer-filter"),
            rx.el.div(_tab("table", "Table"), _tab("chart", "Chart"), class_name="viewer-tabs"),
            class_name="viewer-bar sans",
        ),
        rx.cond(ViewerState.tab == "table", _grid(), _chart()),
        rx.el.div(
            "Click a header to sort · drag a header edge to resize · drag cells to select, Ctrl+C to copy",
            class_name="viewer-foot sans dim",
        ),
        class_name="output viewer",
    )


def widgets_page() -> rx.Component:
    first, *rest = CELLS
    return chrome(cell_view(first, output=data_viewer()), *[cell_view(cell) for cell in rest], look="widgets")
